struct Config {
  std::uint64_t seed = 0;
  std::uint32_t countdown_ticks = 120;
  std::uint8_t input_delay = 2;
};

inline bool valid_hello(const Frame& frame) noexcept {
  if (frame.type != kTypeHello || frame.size != kHelloPayloadBytes) {
    return false;
  }
  ByteReader reader(frame.payload.data(), frame.size);
  std::uint16_t version = 0;
  std::uint32_t rules = 0;
  if (!reader.u16(version)) {
    return false;
  }
  if (!reader.u32(rules)) {
    return false;
  }
  if (!reader.at_end()) {
    return false;
  }
  return version == kProtocolVersion && rules == kRulesetId;
}

inline bool encode_config(std::uint8_t type, const Config& config,
                          Frame& out) noexcept {
  if (type != kTypeOffer && type != kTypeAck) {
    return false;
  }
  if (!valid_config(config)) {
    return false;
  }
  Frame candidate{};
  candidate.type = type;
  ByteWriter writer(candidate.payload.data(), candidate.payload.size());
  const bool ok = writer.u16(kProtocolVersion) &&
                  writer.u32(kRulesetId) &&
                  writer.u64(config.seed) &&
                  writer.u32(config.countdown_ticks) &&
                  writer.u8(config.input_delay) &&
                  writer.u8(kReceiverRolePeer);
  if (!ok || writer.position() != kConfigPayloadBytes) {
    return false;
  }
  candidate.size = kConfigPayloadBytes;
  out = candidate;
  return true;
}

inline bool decode_config(const Frame& frame, std::uint8_t expected,
                          Config& out) noexcept {
  if (expected != kTypeOffer && expected != kTypeAck) {
    return false;
  }
  if (frame.type != expected || frame.size != kConfigPayloadBytes) {
    return false;
  }
  ByteReader reader(frame.payload.data(), frame.size);
  std::uint16_t version = 0;
  std::uint32_t rules = 0;
  Config candidate{};
  std::uint8_t receiver_role = 0;
  if (!reader.u16(version)) {
    return false;
  }
  if (!reader.u32(rules)) {
    return false;
  }
  if (!reader.u64(candidate.seed)) {
    return false;
  }
  if (!reader.u32(candidate.countdown_ticks)) {
    return false;
  }
  if (!reader.u8(candidate.input_delay)) {
    return false;
  }
  if (!reader.u8(receiver_role)) {
    return false;
  }
  if (!reader.at_end()) {
    return false;
  }
  if (version != kProtocolVersion || rules != kRulesetId) {
    return false;
  }
  if (receiver_role != kReceiverRolePeer) {
    return false;
  }
  if (!valid_config(candidate)) {
    return false;
  }
  out = candidate;
  return true;
}

inline HandshakeResult negotiate_host(Connection& connection,
                                      const Config& proposed,
                                      Config& agreed) {
  const Config local = proposed;  // snapshot before touching `agreed`
  if (!valid_config(local)) {
    return HandshakeResult::invalid_local;  // output and connection untouched
  }

  Frame hello{};
  const Connection::ReadReport hello_read = connection.next_frame(hello);
  if (hello_read.state != Connection::ReadState::frame) {
    connection.close();
    return HandshakeResult::receive_failed;
  }
  if (!valid_hello(hello)) {
    connection.close();
    return HandshakeResult::protocol_error;
  }

  Frame offer{};
  if (!encode_config(kTypeOffer, local, offer)) {
    connection.close();  // local was validated, so this path is unexpected
    return HandshakeResult::invalid_local;
  }
  if (!seed_handshake_detail::send_with_budget(connection, offer)) {
    connection.close();
    return HandshakeResult::send_failed;
  }

  Frame ack{};
  const Connection::ReadReport ack_read = connection.next_frame(ack);
  if (ack_read.state != Connection::ReadState::frame) {
    connection.close();
    return HandshakeResult::receive_failed;
  }
  Config echoed{};
  if (!decode_config(ack, kTypeAck, echoed)) {
    connection.close();
    return HandshakeResult::protocol_error;
  }
  if (!equal_config(echoed, local)) {
    connection.close();
    return HandshakeResult::protocol_error;
  }

  agreed = local;
  return HandshakeResult::ready;
}

inline HandshakeResult negotiate_peer(Connection& connection, Config& agreed) {
  const Frame hello = make_hello();
  if (!seed_handshake_detail::send_with_budget(connection, hello)) {
    connection.close();
    return HandshakeResult::send_failed;
  }

  Frame offer{};
  const Connection::ReadReport offer_read = connection.next_frame(offer);
  if (offer_read.state != Connection::ReadState::frame) {
    connection.close();
    return HandshakeResult::receive_failed;
  }
  Config candidate{};
  if (!decode_config(offer, kTypeOffer, candidate)) {
    connection.close();
    return HandshakeResult::protocol_error;
  }

  Frame ack{};
  if (!encode_config(kTypeAck, candidate, ack)) {
    connection.close();  // candidate passed decode_config, so unexpected
    return HandshakeResult::protocol_error;
  }
  if (!seed_handshake_detail::send_with_budget(connection, ack)) {
    connection.close();
    return HandshakeResult::send_failed;
  }

  agreed = candidate;
  return HandshakeResult::ready;
}

bool Connection::adopt(Socket& candidate) noexcept {
    if (active() || !candidate.valid()) return false;
    parser_ = FrameParser{};
    send_closed_ = false;
    peer_eof_ = false;
    socket_ = std::move(candidate);
    return true;
}

